{
  uintptr_t base = LS2K0300_DC_BASE;

  syslog(LOG_INFO,
         "ls2k0300_dc[%s]: pixpll=0x%08lx fb_conf=0x%08lx "
         "pan=0x%08lx pan_tim=0x%08lx orig=0x%08lx\n",
         tag,
         (unsigned long)getreg32(LS2K0300_PIX0_PLL),
         (unsigned long)getreg32(base + LS_DC_FB_CONF),
         (unsigned long)getreg32(base + LS_DC_PAN_CONF),
         (unsigned long)getreg32(base + LS_DC_PAN_TIMING),
         (unsigned long)getreg32(base + LS_DC_FB_ORIG));
  syslog(LOG_INFO,
         "ls2k0300_dc[%s]: hdisp=0x%08lx hsync=0x%08lx "
         "vdisp=0x%08lx vsync=0x%08lx stride=0x%08lx\n",
         tag,
==== TAIL (init/entry) ====
 * Any difference from U-Boot's visible output implicates our register
 * write path; identical output isolates the problem to pattern writing.
 */

static void ls_dc_config_fb_uboot(uint32_t fb_pa)
{
  uintptr_t base = LS2K0300_DC_BASE;

  putreg32(0, base + LS_DC_FB_CONF);
  putreg32(0, base + LS_DC_FB_ADDR0_HI);
  putreg32(0, base + LS_DC_FB_ADDR1_HI);
  putreg32(fb_pa, base + LS_DC_FB_ADDR0);
  putreg32(fb_pa, base + LS_DC_FB_ADDR1);
  putreg32(0, base + LS_DC_DITHER_CONF);
  putreg32(0, base + LS_DC_DITHER_TABLE_LOW);
  putreg32(0, base + LS_DC_DITHER_TABLE_HIGH);
  putreg32(0, base + LS_DC_PAN_CONF);
  putreg32(0x80001111, base + LS_DC_PAN_CONF);
  putreg32(0, base + LS_DC_PAN_TIMING);
  putreg32(0, base + LS_DC_FB_ORIG);
  putreg32(0x05400400, base + LS_DC_HDISPLAY);
  putreg32(0x44b404a0, base + LS_DC_HSYNC);
  putreg32(0x027b0258, base + LS_DC_VDISPLAY);
  putreg32(0x42670264, base + LS_DC_VSYNC);
  putreg32(0x00100104, base + LS_DC_FB_CONF);
  putreg32(0x1000, base + LS_DC_FB_STRIDE);
}

int ls2k0300_dc_initialize(void)
{
  struct ls_dc_pll_cfg cfg;
  int ret;

  (void)g_ls_dc_fb_mem;   /* used for the alias test below */

  /* Snapshot the U-Boot working configuration BEFORE touching anything */

  ls_dc_snapshot("uboot");

  /* Is U-Boot's logo memory still intact at this point? */

  {
    volatile uint32_t *ub =
        (volatile uint32_t *)PHYS_TO_UNCACHED(LS_DC_UBOOT_FB_PA);
    syslog(LOG_INFO,
           "ls2k0300_dc: uboot fb content [0..3] = "
           "0x%08x 0x%08x 0x%08x 0x%08x\n",
           ub[0], ub[1], ub[2], ub[3]);
  }

  /* Alias coherency test: write magic into our static array via the
   * uncached window, then read back through BOTH the uncached alias and
   * the cached alias.  Mismatch => the window does not do what we think.
   */

  {
    volatile uint32_t *unc =
        (volatile uint32_t *)PHYS_TO_UNCACHED(
            (uintptr_t)g_ls_dc_fb_mem - CACHED_MEMORY_ADDR);
    volatile uint32_t *cch = g_ls_dc_fb_mem;
    unc[0] = 0x11111111;
    unc[1] = 0x22222222;
    unc[2] = 0x33333333;
    unc[3] = 0x44444444;
    syslog(LOG_INFO,
           "ls2k0300_dc: alias test uncached-read=0x%08x 0x%08x "
           "cached-read=0x%08x 0x%08x (expect 1111/2222 both)\n",
           unc[0], unc[1], cch[0], cch[1]);
  }

  ls_dc_pinmux_setup();

  ret = ls_dc_cal_freq(LS_DC_PIXCLK_KHZ, &cfg);
  if (ret < 0)
    {
      syslog(LOG_ERR,
             "ls2k0300_dc: no PLL solution for %d kHz pixel clock\n",
             LS_DC_PIXCLK_KHZ);
      return ret;
    }

  ret = ls_dc_config_pll(&cfg);
  if (ret < 0)
    {
      syslog(LOG_ERR, "ls2k0300_dc: pixel PLL lock timeout\n");
      return ret;
    }

  syslog(LOG_INFO,
         "ls2k0300_dc: PLL locked (pstdiv=%lu loopc=%lu frefc=%lu)\n",
         (unsigned long)cfg.l2_div, (unsigned long)cfg.l1_loopc,
         (unsigned long)cfg.l1_frefc);

  /* Phase 1: exact U-Boot replica, scanning U-Boot's own framebuffer.
   * The U-Boot logo should reappear, bright and correct.
   */

  ls_dc_config_fb_uboot(LS_DC_UBOOT_FB_PA);
  up_mdelay(10);
  ls_dc_backlight_on();
  ls_dc_snapshot("nuttx");
  syslog(LOG_INFO,
         "ls2k0300_dc: phase1 = u-boot replica (fb 0x%08x), "
         "logo should reappear\n", LS_DC_UBOOT_FB_PA);

  /* Phase 2: overwrite the logo with the ruler pattern via the
   * uncached alias of U-Boot's framebuffer; no register changes.
   */

  up_mdelay(2000);
  g_ls_dc_fb = (volatile uint32_t *)PHYS_TO_UNCACHED(LS_DC_UBOOT_FB_PA);
  ls_dc_fill_test_pattern(g_ls_dc_fb);
  syslog(LOG_INFO,
         "ls2k0300_dc: phase2 = ruler written over u-boot fb\n");

  /* Verify the ruler landed, via both aliases of u-boot's fb */

  {
    volatile uint32_t *unc = g_ls_dc_fb;
    volatile uint32_t *cch =
        (volatile uint32_t *)PHYS_TO_CACHED(LS_DC_UBOOT_FB_PA);
    syslog(LOG_INFO,
           "ls2k0300_dc: ruler check unc[0]=0x%08x unc[120]=0x%08x "
           "cached[0]=0x%08x cached[120]=0x%08x "
           "(expect ffffff / ff0000 both pairs)\n",
           unc[0], unc[120], cch[0], cch[120]);
  }

  return OK;
}

