   * Must be done even if U-Boot set them up — do not rely on bootloader
   * state surviving into the OS.
   */

  putreg32(LS_PINMUX_DC_VAL, PHYS_TO_UNCACHED(LS_PINMUX_GPIO0_15));
  putreg32(LS_PINMUX_DC_VAL, PHYS_TO_UNCACHED(LS_PINMUX_GPIO16_31));
}

static void ls_dc_backlight_on(void)
{
  static const uint8_t bkl_pins[] = LS_DC_BKL_PINS;
  int i;

  putreg32(LS_PINMUX_GPIO0_15_VAL,
           PHYS_TO_UNCACHED(LS_PINMUX_GPIO0_15));
  putreg32(LS_PINMUX_GPIO80_95_VAL,
           PHYS_TO_UNCACHED(LS_PINMUX_GPIO80_95));

  /* DIR=0 -> output (polarity per ls2k0300_gpio.c), OUT=1 -> backlight
   * on (active-high).  GPIO DIR/OUT are byte-per-pin registers.
   */

  for (i = 0; i < LS_DC_BKL_NPINS; i++)
    {
      putreg8(0, LS2K0300_GPIO_BASE + 0x800 + bkl_pins[i]);
      putreg8(1, LS2K0300_GPIO_BASE + 0x900 + bkl_pins[i]);
    }
}

/* Dump all DC registers.  Called twice: at entry (snapshot of the working
 * U-Boot configuration, prefixed "uboot") and after our own configuration
 * (prefixed "nuttx") — diffing the two pinpoints any mismatch.
 */

