/* Alias coherency probe.
 *
 * Writes a known pattern through the uncached window and reads it back
 * through both windows (and the reverse).  A mismatch means the two
 * virtual addresses do not reach the same memory, which would explain
 * display corruption that no register change can fix.  Kept because this
 * the only way to tell the two windows apart on hardware.
 */

static void ls_dc_alias_probe(void)
{
  volatile uint32_t *unc =
      (volatile uint32_t *)PHYS_TO_UNCACHED(LS_DC_FB_PA);
  volatile uint32_t *cch =
      (volatile uint32_t *)PHYS_TO_CACHED(LS_DC_FB_PA);

  unc[0] = 0x11111111;
  unc[1] = 0x22222222;
  unc[2] = 0x33333333;
  unc[3] = 0x44444444;

  syslog(LOG_INFO,
         "ls2k0300_dc: alias probe via uncached write -> "
         "unc[0]=0x%08x unc[1]=0x%08x cch[0]=0x%08x cch[1]=0x%08x "
         "(expect 11111111/22222222 in all four)\n",
         unc[0], unc[1], cch[0], cch[1]);

  cch[4] = 0x55555555;
  cch[5] = 0x66666666;

  syslog(LOG_INFO,
         "ls2k0300_dc: alias probe via cached write -> "
         "cch[4]=0x%08x cch[5]=0x%08x unc[4]=0x%08x unc[5]=0x%08x "
         "(expect 55555555/66666666 in all four)\n",
         cch[4], cch[5], unc[4], unc[5]);
}

input.new_string:
/* Alias coherency probe.
 *
 * Writes a known pattern through the uncached window and reads it back
 * through both windows (and the reverse).  A mismatch means the two
 * virtual addresses do not reach the same memory, which would explain
 * display corruption that no register change can fix.
 *
 * Measured on this board: uncached writes reach both windows, cached
 * writes stay in the write-back D-cache and are invisible to the uncached
 * window.  So CPU writes must go through the uncached alias -- there is
 * no up_clean_dcache() on LoongArch to force a cached write out.
 *
 * The probe runs on LS_DC_PROBE_SCRATCH rather than the framebuffer: the
 * cached half dirties D-cache lines, and those would later be written
 * back over whatever is on screen.
 */

static void ls_dc_alias_probe(void)
{
  volatile uint32_t *unc =
      (volatile uint32_t *)PHYS_TO_UNCACHED(LS_DC_PROBE_SCRATCH);
  volatile uint32_t *cch =
      (volatile uint32_t *)PHYS_TO_CACHED(LS_DC_PROBE_SCRATCH);

  unc[0] = 0x11111111;
  unc[1] = 0x22222222;
  unc[2] = 0x33333333;
  unc[3] = 0x44444444;

  syslog(LOG_INFO,
         "ls2k0300_dc: alias probe via uncached write -> "
         "unc[0]=0x%08x unc[1]=0x%08x cch[0]=0x%08x cch[1]=0x%08x "
         "(expect 11111111/22222222 in all four)\n",
         unc[0], unc[1], cch[0], cch[1]);

  cch[4] = 0x55555555;
  cch[5] = 0x66666666;

  syslog(LOG_INFO,
         "ls2k0300_dc: alias probe via cached write -> "
         "cch[4]=0x%08x cch[5]=0x%08x unc[4]=0x%08x unc[5]=0x%08x "
         "(cached writes may lag; mismatch here is expected)\n",
         cch[4], cch[5], unc[4], unc[5]);
}

