/* TEMPORARY DIAGNOSTIC -- remove once LS_DC_BKL_PIN is known.
 *
 * Driving more than one backlight candidate at a time lights the panel
 * only dimly, which points at contention on the enable net.  So drive
 * each candidate on its own and hold, and the operator reports which
 * step makes the panel bright.
 */

static void ls_dc_backlight_set(FAR const uint8_t *pins, int npins)
{
  int i;

  for (i = 0; i < npins; i++)
    {
      putreg8(0, LS2K0300_GPIO_BASE + LS2K0300_GPIO_DIR + pins[i]);
      putreg8(1, LS2K0300_GPIO_BASE + LS2K0300_GPIO_OUT + pins[i]);
    }
}

