/* Backlight on.  DIR=0 -> output, OUT=1 -> on (active high).  GPIO
 * direction and output level are byte-per-pin registers.
 */

static void ls_dc_backlight_on(void)
{
  uintptr_t pinmux = PHYS_TO_UNCACHED(LS_PINMUX_GPIO32_47);
  uint32_t val;

  /* Clear only GPIO43's two bits so the pin takes the GPIO function and
   * the rest of the bank (GMAC's GPIO32-39 in particular) is untouched.
   * Reads of this block are unreliable, so fall back to a value that
   * leaves every other pin at MAIN_FUNC when the read looks bogus.
   */

  val = getreg32(pinmux);
  if (val == 0 || val == 0xffffffff)
    {
      val = 0xffffffff;
