  val &= ~(3u << ((LS_DC_BKL_PIN - 32) * 2));
  putreg32(val, pinmux);

  putreg8(0, LS2K0300_GPIO_BASE + LS2K0300_GPIO_DIR + LS_DC_BKL_PIN);
  putreg8(1, LS2K0300_GPIO_BASE + LS2K0300_GPIO_OUT + LS_DC_BKL_PIN);
}
