/****************************************************************************
 * apps/examples/ls_driver_test/test_lcd.c
 *
 * LED status panel on the LS2K0300 RGB LCD.
 *
 * Drives the LEDs itself and draws their state, so the picture and the
 * physical LEDs stay in step -- which is the whole point of the demo.
 *
 * SPDX-License-Identifier: Apache-2.0
 *
 * Licensed to the Apache Software Foundation (ASF) under one or more
 * contributor license agreements.  See the NOTICE file distributed with
 * this work for additional information regarding copyright ownership.
 * The ASF licenses this file to you under the Apache License, Version 2.0
 * (the "License"); you may not use this file except in compliance with the
