/****************************************************************************
 * apps/examples/ls_driver_test/test_touch.c
 *
 * GT9147 capacitive touch diagnostic (M-T1).
 *
 * Runs entirely from userspace on /dev/i2c0 + two GPIOs, so the panel can
 * be brought up before any kernel-side driver exists.  Performs the
 * reset/address-select sequence the datasheet mandates, dumps the identity
 * and resolution registers, then streams live coordinates.
 *
 * SPDX-License-Identifier: Apache-2.0
 *
 * Licensed to the Apache Software Foundation (ASF) under one or more
 * contributor license agreements.  See the NOTICE file distributed with
 * this work for additional information regarding copyright ownership.
 * The ASF licenses this file to you under the Apache License, Version 2.0
 * (the "License"); you may not use this file except in compliance with the
 * License.  You may obtain a copy of the License at
 *
 *   http://www.apache.org/licenses/LICENSE-2.0
 *
 * Unless required by applicable law or agreed to in writing, software
 * distributed under the License is distributed on an "AS IS" BASIS, WITHOUT
 * WARRANTIES OR CONDITIONS OF ANY KIND, either express or implied.  See the
 * License for the specific language governing permissions and limitations
 * under the License.
 *
 ****************************************************************************/

/****************************************************************************
 * Included Files
 ****************************************************************************/

#include <nuttx/config.h>

#include <errno.h>
#include <fcntl.h>
#include <stdio.h>
#include <string.h>
#include <sys/ioctl.h>
#include <unistd.h>

#include <nuttx/arch.h>
#include <nuttx/i2c/i2c_master.h>
#include <nuttx/ioexpander/gpio.h>

#include "ls_driver_test.h"

/****************************************************************************
 * Pre-processor Definitions
 ****************************************************************************/

#define TOUCH_I2C_PATH   "/dev/i2c0"
#define CT_RST_GPIO      55
#define CT_INT_GPIO      42

/* 7-bit address 0x14 is selected by holding INT high while reset is
 * released (GT9147 programming guide p.22).  The alternative is 0x5D.
 */

#define GT_ADDR          0x14

#define GT_CTRL_REG      0x8040   /* 2 = soft reset, 0 = read coordinates */
#define GT_CFGS_REG      0x8047   /* config version */
#define GT_X_MAX_REG     0x8048   /* config X output max (16-bit) */
#define GT_Y_MAX_REG     0x804a   /* config Y output max (16-bit) */
#define GT_CHECK_REG     0x80ff   /* config checksum */
#define GT_PID_REG       0x8140   /* product id, 4 ASCII bytes */
#define GT_X_RES_REG     0x8146   /* x coordinate resolution (16-bit) */
#define GT_Y_RES_REG     0x8148   /* y coordinate resolution (16-bit) */
#define GT_GSTID_REG     0x814e   /* status: bit7 ready, bit3-0 point count */
#define GT_TP1_REG       0x8150   /* point 1: x lo/hi, y lo/hi, size lo/hi */

#define GT_STATUS_READY  0x80

#define TOUCH_POLL_MS    50

/****************************************************************************
 * Private Data
 ****************************************************************************/

static int g_i2c_fd = -1;
static int g_rst_fd = -1;
static int g_int_fd = -1;

/****************************************************************************
 * Private Functions - GPIO
 ****************************************************************************/

static int touch_gpio_output(int pin)
{
  char path[32];
  int fd;

  if (pinctrl_set_gpio_function(pin) < 0)
    {
      printf("[TOUCH] ERROR: pinctrl GPIO%d failed\n", pin);
      return -EIO;
    }

  snprintf(path, sizeof(path), "/dev/gpio%d", pin);
  fd = open(path, O_RDWR);
  if (fd < 0)
    {
      printf("[TOUCH] ERROR: open %s failed: %d\n", path, errno);
      return -errno;
    }

  if (ioctl(fd, GPIOC_SETPINTYPE,
            (unsigned long)GPIO_OUTPUT_PIN) < 0)
    {
      printf("[TOUCH] ERROR: GPIOC_SETPINTYPE on GPIO%d: %d\n",
             pin, errno);
      close(fd);
      return -errno;
    }

  return fd;
}

static void touch_gpio_write(int fd, int value)
{
  ioctl(fd, GPIOC_WRITE, value ? 1 : 0);
}

/* Release CT_INT back to a plain input.  The datasheet calls for a
 * floating input with no internal pull at this point in the sequence.
 */

static void touch_int_release(void)
{
  if (g_int_fd < 0)
    {
      return;
    }

  close(g_int_fd);
  g_int_fd = -1;

  if (pinctrl_set_gpio_function(CT_INT_GPIO) < 0)
    {
      return;
    }

  g_int_fd = open("/dev/gpio" "42", O_RDWR);
  if (g_int_fd < 0)
    {
      return;
    }

  ioctl(g_int_fd, GPIOC_SETPINTYPE, (unsigned long)GPIO_INPUT_PIN);
}

/****************************************************************************
 * Private Functions - I2C (16-bit register address)
 ****************************************************************************/

static int gt_write(FAR const uint8_t *data, int len)
{
  struct i2c_msg_s msg;
  struct i2c_transfer_s trans;

  memset(&msg, 0, sizeof(msg));
  msg.addr = GT_ADDR;
  msg.frequency = 400000;
  msg.buffer = (FAR uint8_t *)data;
  msg.length = len;

  memset(&trans, 0, sizeof(trans));
  trans.msgv = &msg;
  trans.msgc = 1;

  return ioctl(g_i2c_fd, I2CIOC_TRANSFER, (unsigned long)&trans);
}

static int gt_read(FAR uint8_t *data, int len)
{
  struct i2c_msg_s msg[2];
  struct i2c_transfer_s trans;

  memset(msg, 0, sizeof(msg));
  msg[0].addr = GT_ADDR;
  msg[0].frequency = 400000;
  msg[0].buffer = data;
  msg[0].length = 2;            /* 16-bit register address */
  msg[0].flags = 0;

  msg[1].addr = GT_ADDR;
  msg[1].frequency = 400000;
  msg[1].buffer = data + 2;
  msg[1].length = len;
  msg[1].flags = I2C_M_READ;

  memset(&trans, 0, sizeof(trans));
  trans.msgv = msg;
  trans.msgc = 2;

  return ioctl(g_i2c_fd, I2CIOC_TRANSFER, (unsigned long)&trans);
}

/* Read len bytes from a 16-bit register into buf. */

static int gt_read_reg(uint16_t reg, FAR uint8_t *buf, int len)
{
  buf[0] = (uint8_t)(reg >> 8);
  buf[1] = (uint8_t)(reg & 0xff);
  return gt_read(buf, len);
}

static int gt_write_reg(uint16_t reg, uint8_t value)
{
  uint8_t buf[3];

  buf[0] = (uint8_t)(reg >> 8);
  buf[1] = (uint8_t)(reg & 0xff);
  buf[2] = value;
  return gt_write(buf, 3);
}

static uint16_t gt_u16(FAR const uint8_t *p)
{
  return (uint16_t)p[0] | ((uint16_t)p[1] << 8);
}

/****************************************************************************
 * Private Functions - Reset / probe
 ****************************************************************************/

/* Reset and select I2C address 0x14 (GT9147 programming guide p.22):
 *   RST low -> INT high (>100us apart) -> RST high -> wait >5ms ->
 *   INT to floating input -> wait >50ms before any traffic.
 */

static int touch_reset(void)
{
  g_rst_fd = touch_gpio_output(CT_RST_GPIO);
  g_int_fd = touch_gpio_output(CT_INT_GPIO);
  if (g_rst_fd < 0 || g_int_fd < 0)
    {
      return -EIO;
    }

  printf("[TOUCH] reset: RST low, INT high (selects addr 0x%02x)\n",
         GT_ADDR);
  touch_gpio_write(g_rst_fd, 0);
  up_mdelay(1);
  touch_gpio_write(g_int_fd, 1);
  up_mdelay(1);

  touch_gpio_write(g_rst_fd, 1);
  printf("[TOUCH] reset: RST high, waiting 10ms\n");
  up_mdelay(10);

  printf("[TOUCH] reset: INT -> floating input\n");
  touch_int_release();
  up_mdelay(60);

  return OK;
}

static int touch_probe(void)
{
  uint8_t buf[8];
  int ret;

  ret = gt_read_reg(GT_PID_REG, buf, 4);
  if (ret < 0)
    {
      printf("[TOUCH] ERROR: read Product ID failed: %d\n", ret);
      return ret;
    }

  printf("[TOUCH] Product ID  = '%c%c%c%c' (0x%02x 0x%02x 0x%02x 0x%02x)\n",
         buf[2], buf[3], buf[4], buf[5], buf[2], buf[3], buf[4], buf[5]);

  ret = gt_read_reg(GT_X_RES_REG, buf, 4);
  if (ret >= 0)
    {
      printf("[TOUCH] resolution: x=%u y=%u (regs 0x8146..0x8149)\n",
             gt_u16(&buf[2]), gt_u16(&buf[4]));
    }

  ret = gt_read_reg(GT_X_MAX_REG, buf, 4);
  if (ret >= 0)
    {
      printf("[TOUCH] config max : x=%u y=%u (regs 0x8048..0x804b)\n",
             gt_u16(&buf[2]), gt_u16(&buf[4]));
    }

  ret = gt_read_reg(GT_CFGS_REG, buf, 1);
  if (ret >= 0)
    {
      printf("[TOUCH] config ver = 0x%02x\n", buf[2]);
    }

