int test_touch(void)
{
  uint8_t buf[8];
  int ret;

  printf("=== GT9147 Touch Diagnostic ===\n\n");
  printf("[TOUCH] Bus: %s, SDA=GPIO49 SCL=GPIO48\n", TOUCH_I2C_PATH);
  printf("[TOUCH] CT_RST=GPIO%d, CT_INT=GPIO%d\n\n",
         CT_RST_GPIO, CT_INT_GPIO);

  g_i2c_fd = open(TOUCH_I2C_PATH, O_RDWR);
  if (g_i2c_fd < 0)
    {
      printf("[TOUCH] ERROR: open %s failed: %d\n", TOUCH_I2C_PATH, errno);
      return -errno;
    }

  ret = touch_reset();
  if (ret < 0)
    {
      goto out;
    }

  ret = touch_probe();
  if (ret < 0)
    {
      goto out;
    }

  printf("\n[TOUCH] polling for touches (Ctrl-C to stop)...\n");

  for (; ; )
    {
      ret = gt_read_reg(GT_GSTID_REG, buf, 1);
      if (ret < 0)
        {
          printf("[TOUCH] ERROR: status read failed: %d\n", ret);
          up_mdelay(200);
          continue;
        }

      if (buf[2] & GT_STATUS_READY)
        {
          int npoints = buf[2] & 0x0f;

          if (npoints > 0 && npoints < 6)
            {
              ret = gt_read_reg(GT_TP1_REG, buf, 6);
              if (ret >= 0)
                {
                  uint16_t x = gt_u16(&buf[2]);
                  uint16_t y = gt_u16(&buf[4]);
                  uint16_t size = gt_u16(&buf[6]);

                  printf("[TOUCH] %d point(s): x=%u y=%u size=%u "
                         "(raw, before mapping)\n",
                         npoints, x, y, size);
                }
            }
          else if (npoints == 0)
            {
              printf("[TOUCH] released\n");
            }

          /* bit7 must be cleared or the chip will not report again */

          gt_write_reg(GT_GSTID_REG, 0);
        }

      up_mdelay(TOUCH_POLL_MS);
    }

out:
  if (g_i2c_fd >= 0)
    {
      close(g_i2c_fd);
      g_i2c_fd = -1;
    }

  return ret;
}

