/****************************************************************************
 * Private Functions - I2C (16-bit register address)
 *
 * Access is split into two independent transfers (write the register
 * address, then read) rather than one combined write+read.  This SoC's
 * I2C controller does not handle a repeated-start multi-message
 * transfer -- test_eeprom.c uses the same two-step pattern for AT24C02,
 * which needs exactly this kind of "set address then read" access.
 ****************************************************************************/

static int gt_xfer(FAR struct i2c_msg_s *msg, int msgc)
{
  struct i2c_transfer_s trans;

  memset(&trans, 0, sizeof(trans));
  trans.msgv = msg;
  trans.msgc = msgc;

  return ioctl(g_i2c_fd, I2CIOC_TRANSFER, (unsigned long)&trans);
}

static int gt_write(FAR const uint8_t *data, int len)
{
  struct i2c_msg_s msg;

  memset(&msg, 0, sizeof(msg));
  msg.addr = GT_ADDR;
  msg.frequency = 400000;
  msg.buffer = (FAR uint8_t *)data;
  msg.length = len;
  msg.flags = 0;

  return gt_xfer(&msg, 1);
}

static int gt_read(FAR uint8_t *data, int len)
{
  struct i2c_msg_s msg;

  memset(&msg, 0, sizeof(msg));
  msg.addr = GT_ADDR;
  msg.frequency = 400000;
  msg.buffer = data;
  msg.length = len;
  msg.flags = I2C_M_READ;

  return gt_xfer(&msg, 1);
}

/* Read len bytes from a 16-bit register into buf[2..2+len-1]; buf[0..1]
 * carry the register address for the write phase.
 */

static int gt_read_reg(uint16_t reg, FAR uint8_t *buf, int len)
{
  int ret;

  buf[0] = (uint8_t)(reg >> 8);
  buf[1] = (uint8_t)(reg & 0xff);

  ret = gt_write(buf, 2);
  if (ret < 0)
    {
      return ret;
    }

  return gt_read(buf + 2, len);
}

