/* Read len bytes starting at a 16-bit register into buf[2..2+len-1].
 *
 * Each byte is fetched with its own write+read pair rather than one
 * multi-byte read.  Two reasons to be conservative here: the multi-byte
 * read after a register-address write is what failed on hardware, and a
 * per-byte address write also survives the case where the chip drops its
 * register pointer on STOP.
 */

static int gt_read_reg(uint16_t reg, FAR uint8_t *buf, int len)
{
  int i;

  for (i = 0; i < len; i++)
    {
      uint16_t r = reg + i;
      int ret;

      buf[0] = (uint8_t)(r >> 8);
      buf[1] = (uint8_t)(r & 0xff);

      ret = gt_write(buf, 2);
      if (ret < 0)
        {
          printf("[TOUCH]   write reg 0x%04x FAILED: %d\n", r, ret);
          return ret;
        }

      ret = gt_read(buf + 2 + i, 1);
      if (ret < 0)
        {
          printf("[TOUCH]   read  reg 0x%04x FAILED: %d\n", r, ret);
          return ret;
        }
    }

  return OK;
}

