/* Datasheet read: one combined transfer -- write the 16-bit register
 * address, repeated START, then read.  This is also exactly what the
 * kernel gt9xx driver does (gt9xx_i2c_read uses msgv[2]).
 *
 * The earlier failure of this shape was measured *before* the I2C0 pinmux
 * was fixed, i.e. while the bus was not usable at all, so it is retried
 * here as the primary method.
 */

static int gt_read_reg_combined(uint16_t reg, FAR uint8_t *buf, int len)
{
  struct i2c_msg_s msg[2];

  buf[0] = (uint8_t)(reg >> 8);
  buf[1] = (uint8_t)(reg & 0xff);

  memset(msg, 0, sizeof(msg));
  msg[0].addr = GT_ADDR;
  msg[0].frequency = TOUCH_I2C_FREQ;
  msg[0].buffer = buf;
  msg[0].length = 2;
  msg[0].flags = 0;

  msg[1].addr = GT_ADDR;
  msg[1].frequency = TOUCH_I2C_FREQ;
  msg[1].buffer = buf + 2;
  msg[1].length = len;
  msg[1].flags = I2C_M_READ;

  return gt_xfer(msg, 2);
}

