/* Decode the controller state at the moment a transfer gives up.  Without
 * this a timeout (-ETIMEDOUT) is indistinguishable from "the address byte
 * never shifted out" and "the slave held the line".
 */

static void ls2k0300_i2c_dump_status(FAR struct ls2k0300_i2c_priv_s *priv,
                                     FAR const char *where)
{
  uint32_t sr1 = i2c_getreg(priv, LS2K0300_I2C_SR1);
  uint32_t sr2 = i2c_getreg(priv, LS2K0300_I2C_SR2);
  uint32_t cr1 = i2c_getreg(priv, LS2K0300_I2C_CR1);

  syslog(LOG_ERR,
         "i2c@%p %s: SR1=0x%08lx [SB=%d ADDR=%d BTF=%d RXNE=%d TXE=%d "
         "BERR=%d ARLO=%d AF=%d] SR2=0x%08lx [BUSY=%d] CR1=0x%08lx\n",
         priv, where, (unsigned long)sr1,
         !!(sr1 & I2C_SR1_SB), !!(sr1 & I2C_SR1_ADDR),
         !!(sr1 & I2C_SR1_BTF), !!(sr1 & I2C_SR1_RXNE),
         !!(sr1 & I2C_SR1_TXE), !!(sr1 & I2C_SR1_BERR),
         !!(sr1 & I2C_SR1_ARLO), !!(sr1 & I2C_SR1_AF),
         (unsigned long)sr2, !!(sr2 & I2C_SR2_BUSY),
         (unsigned long)cr1);
}

