static int ls2k0300_i2c_wait_status(struct ls2k0300_i2c_priv_s *priv,
                                   uint32_t mask, bool set,
                                   uint32_t timeout_us)
{
  uint32_t elapsed = 0;
  uint32_t status = 0;

  while (elapsed < timeout_us)
    {
      status = i2c_getreg(priv, LS2K0300_I2C_SR1);

      if (set && (status & mask))
        {
          return OK;
        }

      if (!set && !(status & mask))
        {
          return OK;
        }

      up_udelay(10);
      elapsed += 10;
    }

  /* Report the status as it was seen during the wait.  Reading SR1 again
   * would clear the flags and hand back an all-zero register, which looks
   * like a dead controller and hides the real cause.
   */

  syslog(LOG_ERR,
         "i2c@%p wait_status mask=0x%lx set=%d TIMED OUT: "
         "last SR1=0x%08lx CR1=0x%08lx\n",
         priv, (unsigned long)mask, set,
         (unsigned long)status,
         (unsigned long)i2c_getreg(priv, LS2K0300_I2C_CR1));

  return -ETIMEDOUT;
}

