/****************************************************************************
 * apps/examples/ls_lvgl/ls_lvgl.c
 *
 * Device status console on the LS2K0300 800x480 RGB panel (M-L1).
 *
 * Two-column layout: the left column holds the actuators (LED switches,
 * PWM slider, buzzer button) and the right column the sampled values.
 * Rendering goes straight to /dev/fb0 through the NuttX LVGL backend, so
 * the drawing buffer is the framebuffer itself and no extra RAM is taken.
 *
 * SPDX-License-Identifier: Apache-2.0
 *
 * Licensed to the Apache Software Foundation (ASF) under one or more
 * contributor license agreements.  See the NOTICE file distributed with
 * this work for additional information regarding copyright ownership.
 * The ASF licenses this file to you under the Apache License, Version 2.0
 * (the "License"); you may not use this file except in compliance with the
 * License.  You may obtain a copy of the License at
 *
 *   http://www.apache.org/licenses/LICENSE-2.0
 *
 * Unless required by applicable law or agreed to in writing, software
 * distributed under the License is distributed on an "AS IS" BASIS, WITHOUT
 * WARRANTIES OR CONDITIONS OF ANY KIND, either express or implied.  See the
 * License for the specific language governing permissions and limitations
 * under the License.
 *
 ****************************************************************************/

/****************************************************************************
 * Included Files
 ****************************************************************************/

#include <nuttx/config.h>

#include <errno.h>
#include <fcntl.h>
#include <stdio.h>
#include <string.h>
#include <sys/ioctl.h>
#include <unistd.h>

#include <nuttx/timers/rtc.h>

#include <lvgl/lvgl.h>

/****************************************************************************
 * Pre-processor Definitions
 ****************************************************************************/

#define UI_BG_COLOR      0x1a2332
#define UI_PANEL_COLOR   0x222e42
#define UI_TEXT_COLOR     0xffffff
#define UI_DIM_COLOR     0x8a94a6
#define UI_ACCENT_COLOR  0x34c759

#define UI_MARGIN        16
#define UI_TITLE_H       48
#define UI_COL_GAP       16
#define UI_ROW_GAP       10

#define UI_COL_W         ((800 - UI_MARGIN * 2 - UI_COL_GAP) / 2)

#define UI_VALUE_LEN     24

/****************************************************************************
 * Private Types
 ****************************************************************************/

/* One row of the console: a caption on the left and either a control or a
 * live value on the right.  Adding a peripheral later is one entry here.
 */

struct ui_row_s
{
  FAR const char *caption;
  lv_obj_t *control;            /* switch / slider / button, or NULL */
  lv_obj_t *value;              /* label, or NULL when control is set */
  char value_buf[UI_VALUE_LEN];
};

/****************************************************************************
 * Private Data
 ****************************************************************************/

static struct ui_row_s g_left_rows[] =
{
  { "LED RED",   NULL, NULL, "" },
  { "LED GREEN", NULL, NULL, "" },
  { "PWM BLUE",  NULL, NULL, "" },
  { "BUZZER",    NULL, NULL, "" },
};

static struct ui_row_s g_right_rows[] =
{
  { "ADC CH0", NULL, NULL, "--" },
  { "TEMP",    NULL, NULL, "--" },
  { "LIGHT",   NULL, NULL, "--" },
  { "RTC",     NULL, NULL, "--:--:--" },
};

#define UI_LEFT_ROWS   (sizeof(g_left_rows) / sizeof(g_left_rows[0]))
#define UI_RIGHT_ROWS  (sizeof(g_right_rows) / sizeof(g_right_rows[0]))

static int g_rtc_fd = -1;

/****************************************************************************
 * Private Functions
 ****************************************************************************/

static lv_obj_t *ui_make_row(FAR struct ui_row_s *row,
                             FAR lv_obj_t *parent, bool with_control)
{
  lv_obj_t *box = lv_obj_create(parent);
  lv_obj_t *caption;
  lv_obj_t *right;

  lv_obj_remove_style_all(box);
  lv_obj_set_size(box, UI_COL_W, 44);
  lv_obj_set_flex_flow(box, LV_FLEX_FLOW_ROW);
  lv_obj_set_flex_align(box, LV_FLEX_ALIGN_SPACE_BETWEEN,
                        LV_FLEX_ALIGN_CENTER, LV_FLEX_ALIGN_CENTER);
  lv_obj_set_style_pad_hor(box, 12, 0);
  lv_obj_set_style_bg_color(box, lv_color_hex(UI_PANEL_COLOR), 0);
  lv_obj_set_style_bg_opa(box, LV_OPA_COVER, 0);
  lv_obj_set_style_radius(box, 8, 0);

  caption = lv_label_create(box);
  lv_label_set_text(caption, row->caption);
  lv_obj_set_style_text_color(caption, lv_color_hex(UI_TEXT_COLOR), 0);

  if (with_control)
    {
      right = lv_switch_create(box);
    }
  else
    {
      right = lv_label_create(box);
      lv_label_set_text(right, row->value);
      lv_obj_set_style_text_color(right, lv_color_hex(UI_ACCENT_COLOR), 0);
      row->value = right;
    }

  row->control = with_control ? right : NULL;
  return box;
}

/* Builds one column: a heading plus its rows.  Both columns use the same
 * row helper so the two halves line up.
 */

static void ui_build_column(FAR lv_obj_t *parent,
                            FAR const char *heading,
                            FAR struct ui_row_s *rows, int nrows,
                            bool with_control)
{
  lv_obj_t *title;
  int i;

  title = lv_label_create(parent);
  lv_label_set_text(title, heading);
  lv_obj_set_style_text_color(title, lv_color_hex(UI_DIM_COLOR), 0);
  lv_obj_set_style_text_font(title, &lv_font_montserrat_16, 0);
  lv_obj_set_style_pad_bottom(title, 6, 0);

  for (i = 0; i < nrows; i++)
    {
      ui_make_row(&rows[i], parent, with_control);
    }
}

static void ui_build(void)
{
  lv_obj_t *scr = lv_screen_active();
  lv_obj_t *title;
  lv_obj_t *left;
  lv_obj_t *right;

  lv_obj_set_style_bg_color(scr, lv_color_hex(UI_BG_COLOR), 0);
  lv_obj_set_style_bg_opa(scr, LV_OPA_COVER, 0);
  lv_obj_set_style_pad_all(scr, UI_MARGIN, 0);

  lv_obj_set_flex_flow(scr, LV_FLEX_FLOW_COLUMN);
  lv_obj_set_flex_align(scr, LV_FLEX_ALIGN_START, LV_FLEX_ALIGN_START,
                        LV_FLEX_ALIGN_START);
  lv_obj_set_style_pad_row(scr, UI_ROW_GAP, 0);

  title = lv_label_create(scr);
  lv_label_set_text(title, "LS2K0300 DEVICE STATUS");
  lv_obj_set_style_text_color(title, lv_color_hex(UI_TEXT_COLOR), 0);
  lv_obj_set_style_text_font(title, &lv_font_montserrat_20, 0);

  /* The two columns sit side by side below the title. */

  {
    lv_obj_t *cols = lv_obj_create(scr);
    lv_obj_remove_style_all(cols);
    lv_obj_set_size(cols, 800 - UI_MARGIN * 2, LV_SIZE_CONTENT);
    lv_obj_set_flex_flow(cols, LV_FLEX_FLOW_ROW);
    lv_obj_set_flex_align(cols, LV_FLEX_ALIGN_SPACE_BETWEEN,
                          LV_FLEX_ALIGN_START, LV_FLEX_ALIGN_START);
    lv_obj_set_style_pad_column(cols, UI_COL_GAP, 0);
    lv_obj_set_style_pad_row(cols, UI_ROW_GAP, 0);

    left = lv_obj_create(cols);
    lv_obj_remove_style_all(left);
    lv_obj_set_size(left, UI_COL_W, LV_SIZE_CONTENT);
    lv_obj_set_flex_flow(left, LV_FLEX_FLOW_COLUMN);
    lv_obj_set_style_pad_row(left, UI_ROW_GAP, 0);

    right = lv_obj_create(cols);
    lv_obj_remove_style_all(right);
    lv_obj_set_size(right, UI_COL_W, LV_SIZE_CONTENT);
    lv_obj_set_flex_flow(right, LV_FLEX_FLOW_COLUMN);
    lv_obj_set_style_pad_row(right, UI_ROW_GAP, 0);
  }

  ui_build_column(left, "CONTROL", g_left_rows, UI_LEFT_ROWS, true);
  ui_build_column(right, "STATUS", g_right_rows, UI_RIGHT_ROWS, false);
}

/* Only the RTC is sampled here: it needs no bus and proves the console is
 * alive.  The I2C-backed values (ADC, temperature, light) arrive with the
 * touch work, which owns the sensor bus.
 */

static void ui_tick(void)
{
  struct rtc_time rtctime;
  FAR struct ui_row_s *row = &g_right_rows[UI_RIGHT_ROWS - 1];

  if (g_rtc_fd < 0 || row->value == NULL)
    {
      return;
    }

  if (ioctl(g_rtc_fd, RTC_RD_TIME,
            (unsigned long)(uintptr_t)&rtctime) == 0)
    {
      snprintf(row->value_buf, sizeof(row->value_buf), "%02d:%02d:%02d",
               rtctime.tm_hour, rtctime.tm_min, rtctime.tm_sec);
      lv_label_set_text(row->value, row->value_buf);
    }
}

/****************************************************************************
 * Public Functions
 ****************************************************************************/

int main(int argc, FAR char *argv[])
{
  lv_nuttx_dsc_t info;
  lv_nuttx_result_t result;

  printf("=== LS2K0300 LVGL Console ===\n");

  lv_init();
  lv_nuttx_dsc_init(&info);
  lv_nuttx_init(&info, &result);

  if (result.disp == NULL)
    {
      printf("ERROR: lv_nuttx_init failed (no /dev/fb0?)\n");
      return -ENODEV;
    }

  ui_build();

  g_rtc_fd = open("/dev/rtc0", O_RDONLY);
  if (g_rtc_fd < 0)
    {
      printf("WARNING: /dev/rtc0 unavailable (%d), RTC row stays --\n",
             errno);
    }

  printf("console up, Ctrl-C to stop\n");

  for (; ; )
    {
      uint32_t idle;

      ui_tick();
      idle = lv_timer_handler();
      usleep((idle ? idle : 1) * 1000);
    }

  /* Not reached. */

  lv_nuttx_deinit(&result);
  lv_deinit();
  return OK;
}

