    {
      return;
    }

  /* A passive buzzer needs a real square wave; usleep() cannot resolve
   * below one tick, so busy-wait the half period.
   */

  for (i = 0; i < edges; i++)
    {
      ioctl(g_buzz_fd, GPIOC_WRITE, (i & 1) ? 0 : 1);
      up_udelay(BUZZER_HALF_US);
    }

  ioctl(g_buzz_fd, GPIOC_WRITE, 0);
}

